#[derive(Debug, Clone, Copy)]
pub(crate) struct Limits {
    /// Largest input accepted by [`validate_bytes`] (512 MiB).
    pub input_bytes: usize,
    /// Most zip entries examined (20 000).
    pub entries: usize,
    /// Largest single decompressed part examined (256 MiB).
    pub part_bytes: u64,
    /// Largest total of all decompressed parts (512 MiB).
    pub total_bytes: u64,
    /// Deepest XML element nesting examined (512).
    pub depth: usize,
    /// Most XML events examined per part (2 000 000).
    pub events: usize,
    /// Most collected facts per category (200 000).
    pub facts: usize,
    /// Most coverage notes recorded (10 000).
    pub notes: usize,
    /// Most findings recorded per rule (5 000).
    pub findings_per_rule: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum Verdict {
    /// No Corrupt or Error finding, and every required input was examined.
    Pass,
    /// At least one Corrupt or Error finding.
    Fail,
    /// A required input could not be examined at all.
    Incomplete,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum Severity {
    /// Structurally unusable as a document (for example, not a ZIP or missing its manifest).
    Corrupt,
    /// Consumer refusal, repair, or loss of referenced content, as calibrated for this rule.
    Error,
    /// A tolerated defect or degradation worth reporting, including some specification violations.
    Warning,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum Evidence {
    /// Structurally certain at the XML/package level; does not establish a consumer reaction.
    ByConstruction,
    /// Documented by OOXML or Microsoft's format/implementation specifications.
    MsDocumented,
    /// Consumer reaction observed on a defective fixture in a named Word oracle, with fixture,
    /// date, and consumer/open-path details recorded in corpus/EVIDENCE.md. One consumer's reaction
    /// does not establish another's.
    Observed,
    /// Concluded from the package contents.
    Inferred,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Finding {
    /// Stable rule id, e.g. `"REL-DANGLING"`.
    pub rule: &'static str,
    pub severity: Severity,
    pub evidence: Evidence,
    /// The package part the finding belongs to, if any.
    pub part: Option<String>,
    /// Human-readable, naming the concrete id or value involved.
    pub message: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Report {
    pub verdict: Verdict,
    /// Deterministic order: by part, then rule id, then message.
    pub findings: Vec<Finding>,
    /// Things skipped within a completed run.
    pub coverage_notes: Vec<String>,
    /// Every rule id that executed, in the documented order.
    pub checks_run: Vec<&'static str>,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct RuleSpec {
    pub id: &'static str,
    pub severity: Severity,
    pub evidence: Evidence,
}

#[derive(Default)]
pub(crate) struct Acc {
    findings: Vec<Finding>,
    coverage: Vec<String>,
    checks: Vec<&'static str>,
    incomplete: bool,
    limits: Limits,
    rule_counts: HashMap<&'static str, usize>,
    /// An entry was found whose identity could not be recovered. It could be any part, so no
    /// absence conclusion is established while this is set (see [`contracts_generated::PACKAGE_ABSENCE_RULES`]).
    unknown_unreadable: bool,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Compat {
    Off,
    On,
    Unknown,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Completeness {
    Complete,
    Incomplete(Reason),
}

#[derive(Clone, Debug)]
pub(crate) struct Observed<T> {
    observed_value: T,
    observed_status: Completeness,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum OwnerContext {
    Main(String),
    Glossary(String),
    Fallback,
}

#[derive(Debug)]
pub(crate) enum Membership {
    Owned(Vec<OwnerId>),
    Unowned,
    Unknown,
}

#[derive(Debug)]
pub(crate) struct PartGraph {
    memberships: BTreeMap<PartId, Membership>,
    budget_exhausted: bool,
    memberships_complete: bool,
}

#[derive(Default)]
pub(crate) struct ContentTypes {
    overrides: HashMap<String, String>,
    /// Later declarations were not examined; absence and Default fallbacks are unestablished.
    pub incomplete: bool,
    defaults: HashMap<String, String>,
    /// Extensions with more than one Default entry (lowercased).
    pub dup_defaults: BTreeSet<String>,
    /// Part names with more than one Override entry (lowercased, leading `/` stripped).
    pub dup_overrides: BTreeSet<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Resolution<T> {
    /// The uniquely observed candidate.
    One(T),
    /// Complete discovery found no candidate.
    Absent,
    /// Distinct candidates compete.
    Ambiguous(Reason),
    /// Discovery could not establish a candidate set.
    Unknown(Reason),
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
enum NumericKey {
    Valid(String),
    Invalid(String),
}

#[derive(Clone, Debug)]
        pub(crate) struct $name {
            key: NumericKey,
            raw: String,
        }

#[derive(Clone, Default)]
pub(crate) struct StoryFacts {
    pub comment_defs: Observed<Vec<(DecimalId, String)>>,
    pub comment_refs: Observed<Vec<(DecimalId, String)>>,
    /// `w:commentRangeStart` occurrences across this part. A plain counter, not
    /// a pooled fact: 32k ranges must not consume the pooled fact budget.
    pub comment_range_starts: usize,
    /// `w:bookmarkStart` occurrences in this part (compat-count counter).
    pub bookmark_starts: usize,
    /// `w:permStart` occurrences in this part (compat-count counter).
    pub perm_starts: usize,
    /// `w:moveFromRangeStart` + `w:moveToRangeStart` occurrences in this part
    /// (compat-count counter).
    pub move_range_starts: usize,
    /// `w14:paraId` values on paragraphs in comments.xml (for `COMMENTEX-LINK`).
    pub comment_para_ids: Observed<Vec<(HexId, String)>>,
    pub docpr: Observed<Vec<(DecimalId, String)>>,
    pub bookmarks: Observed<Vec<(DecimalId, String)>>,
    pub revisions: Observed<Vec<(DecimalId, String)>>,
    pub footnote_refs: Observed<Vec<(DecimalId, String)>>,
    pub endnote_refs: Observed<Vec<(DecimalId, String)>>,
    pub footnote_defs: Observed<Vec<(DecimalId, String)>>,
    pub endnote_defs: Observed<Vec<(DecimalId, String)>>,
    pub header_refs: Observed<Vec<(RelId, String)>>,
    pub footer_refs: Observed<Vec<(RelId, String)>>,
    pub style_refs: Observed<Vec<(StyleId, String)>>,
    /// `w:numId/@w:val` values used by `w:numPr` in story parts (for `NUM-DANGLING`).
    pub num_ids: Observed<Vec<(DecimalId, String)>>,
}

#[derive(Clone)]
pub(crate) struct RefFact {
    pub attr: String,
    pub value: RelId,
    /// The reference is the image target of an image element (`a:blip`, `v:imagedata`).
    pub image: bool,
}

#[derive(Clone, Copy)]
enum Exhaustion {
    Events,
    Depth,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum TcEnd {
    /// A paragraph satisfies the cell's terminal-block requirement.
    Paragraph,
    /// A nested table: the one non-paragraph ending calibration shows Word rejecting.
    Other,
}

#[derive(Default)]
struct State {
    /// This settings part carries `w:uiCompat97to2003` (the Word 97–2003
    /// compatibility flag the count limits key on).
    compat_97: bool,
    /// Special note definitions in this part: (id, is_endnote, w:type).
    special_notes: Vec<(DecimalId, bool, String)>,
    /// Ids listed by `w:footnotePr` elements in this part.
    note_listings_f: Vec<DecimalId>,
    /// Ids listed by `w:endnotePr` elements in this part.
    note_listings_e: Vec<DecimalId>,
    /// A note definition or listing was dropped at the fact budget.
    note_capped: bool,
    declared: Vec<Vec<String>>,
    frames: Vec<Frame>,
    del_depth: i64,
    wrapper_depth: i64,
    fld_depth: i64,
    fld_extra_end: usize,
    move_from_start: BTreeSet<DecimalId>,
    move_from_end: BTreeSet<DecimalId>,
    move_to_start: BTreeSet<DecimalId>,
    move_to_end: BTreeSet<DecimalId>,
    move_from_names: BTreeSet<String>,
    move_to_names: BTreeSet<String>,
    move_start_ids: Vec<DecimalId>,
    bookmark_starts: BTreeSet<DecimalId>,
    bookmark_ends: BTreeSet<DecimalId>,
    /// Comment range ids in the parts where Word honours ranges (main and
    /// glossary stories, outside text boxes); paired at scan completion.
    comment_range_start_ids: BTreeSet<DecimalId>,
    comment_range_end_ids: BTreeSet<DecimalId>,
    /// Canonical `w14:paraId` values seen in this part, with their
    /// occurrence contexts (PARAID-DUP; judged at the prefix report —
    /// a repeat across one block's Choice and Fallback is excused,
    /// every other repeat is a duplicate).
    para_ids: BTreeMap<HexId, ParaOcc>,
    /// The stack of enclosing `mc:AlternateContent` blocks: a sequence
    /// number per block and the branch instance the scan is currently
    /// inside it (0 = inside no branch element).
    alt_stack: Vec<AltCtx>,
    /// Sequence number source for `alt_stack` entries.
    alt_seq: u32,
    /// Instance number source for branch elements (`mc:Choice` /
    /// `mc:Fallback`): every branch element gets its own number, so
    /// two Choices of one block are distinct alternatives.
    alt_branch_seq: u32,
    /// Nonzero while inside an `mc:AlternateContent` subtree.
    alt_depth: usize,
    /// One coverage note per part that contains `mc:AlternateContent`.
    alt_noted: bool,
    /// The per-category fact budget, copied from [`crate::Limits`].
    fact_cap: usize,
    /// A fact budget was exhausted; no further facts are collected.
    fact_capped: bool,
    /// The reference budget was exhausted; no further `r:id`/`r:embed`/`r:link` values are kept.
    refs_capped: bool,
    facts: StoryFacts,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum DecodeError {
    /// The bytes are not valid text in the declared encoding (invalid UTF-8, an unpaired surrogate,
    /// or a truncated trailing unit): the part is not well-formed XML.
    Malformed(String),
    /// The part declares an encoding this checker does not support; its checks are skipped.
    Unsupported(String),
    /// The part begins an XML declaration that does not terminate within the scan bound, so the
    /// encoding cannot be decided (H6); the part's checks are skipped and the run is INCOMPLETE.
    IncompleteDeclaration,
}

#[derive(Default)]
struct ParaOcc {
    /// Retained representative paths, pairwise non-conflicting.
    reps: Vec<ParaPath>,
    /// A pair of occurrences that can coexist was seen: a duplicate.
    conflict: bool,
    /// More mutually excused occurrences arrived than are retained;
    /// uniqueness is unprovable for this value.
    overflow: bool,
}

#[derive(Default)]
pub(crate) struct NumberingDefs {
    pub num_ids: Vec<DecimalId>,
    pub abstract_ids: Vec<DecimalId>,
    /// Each `w:num`'s `numId` and the `w:abstractNumId` it references, if any.
    pub num_to_abstract: Vec<(DecimalId, Option<DecimalId>)>,
    /// The per-category budget was exhausted while parsing.
    pub capped: bool,
}

#[derive(Default)]
pub(crate) struct StyleDef {
    /// The `w:style/@w:styleId` value, if present.
    pub id: Option<StyleId>,
    /// The first `w:name/@w:val` inside the style, if present.
    pub name: Option<String>,
    /// Whether a `w:name` child was seen at all: the FIRST name
    /// element owns the primary-name slot even when it carries no
    /// value, so a later sibling never replaces it.
    pub name_seen: bool,
    /// The `w:style/@w:type` value, if present.
    pub style_type: Option<String>,
}

#[derive(Default)]
pub(crate) struct CommentEx {
    pub entries: Vec<(HexId, Option<HexId>)>,
    /// The per-category budget was exhausted while parsing.
    pub capped: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum MaxOccurs {
    /// At most this many occurrences.
    Limited(u16),
    /// No upper bound (`maxOccurs="unbounded"`).
    Unbounded,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Compositor {
    /// `xsd:sequence`: slots in a fixed order.
    Sequence,
    /// `xsd:choice`: one of the slots sharing a `choice_group`.
    Choice,
    /// `xsd:all`: each slot at most once, any order.
    All,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct ChildSpec {
    /// Prefixed element name, e.g. `w:tblPr`; `<any>` for an `xsd:any` wildcard.
    pub name: &'static str,
    /// Minimum occurrences, with the enclosing particles' minOccurs multiplied in.
    pub min: u16,
    /// Maximum occurrences, with the enclosing particles' maxOccurs multiplied in.
    pub max: MaxOccurs,
    /// The compositor this slot sits in.
    pub compositor: Compositor,
    /// The choice group id shared by the members of one `xsd:choice`, if any.
    pub choice_group: Option<&'static str>,
    /// Index of this slot in the type's flattened child list.
    pub position: u16,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct TypeModel {
    /// Namespace-qualified type key, e.g. `w:CT_Tc`, `a:CT_FontCollection`.
    pub key: &'static str,
    /// The type's child slots in flattened schema order.
    pub children: &'static [ChildSpec],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct Variant {
    /// The type key of this declaration (may name a simple or out-of-scope type
    /// that has no [`TypeModel`]; such an element is unmodelled).
    pub type_key: &'static str,
    /// Parent type keys this variant is selected under (group contexts expanded).
    pub contexts: &'static [&'static str],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct ElementModel {
    /// Prefixed element name, e.g. `w:sectPr`.
    pub name: &'static str,
    /// The type key used in the most declaration contexts.
    pub canonical: &'static str,
    /// Every declared type, sorted by type key.
    pub variants: &'static [Variant],
}

package_producer_source:
/// Load a zip into the package model. Returns `None` only when the input is not a readable zip
/// (after a `PKG-NOT-ZIP` finding): every other problem becomes a finding or a coverage note.
pub(crate) fn load(bytes: &[u8], acc: &mut Acc) -> Option<Package> {
    observation_contract! {
        rules: "PKG-NO-CONTENT-TYPES,PKG-NO-MAIN,PKG-NOT-ZIP";
        collections: "field.bytes*1,field.entries*6,field.incomplete*5,field.rels*1,parser.parse_content_types*1,type.Vec*2";
        scope: "source-local bounded extraction; no implicit document owner";
        loss: "source unavailable or malformed; XML event/depth budget; category allocation cap";
        fallback: "retain proven prefix presence and duplicates; return loss to the caller; no negative membership from an incomplete set";
        package_loss: "PKG-NO-CONTENT-TYPES,PKG-NO-MAIN";
    }

    acc.ran("PKG-NOT-ZIP");
    let Ok(mut zip) = zip::ZipArchive::new(Cursor::new(bytes)) else {
        acc.add("PKG-NOT-ZIP", None, "the input is not a readable zip archive".to_string());
        return None;
    };
    let limits = acc.limits;
    let entries_truncated = zip.len() > limits.entries;
    if entries_truncated {
        acc.note(format!("the archive declares {} entries; only the first {} were examined", zip.len(), limits.entries));
        acc.set_incomplete();
    }
    let limit = zip.len().min(limits.entries);
    let mut entries = Vec::new();
    let mut total: u64 = 0;
    // Set when an entry that failed to open could not be named at all. Its identity is unknown, so
    // nothing can be concluded about what is absent from the package while it is set.
    let mut unknown_unreadable = false;
    for i in 0..limit {
        // The identity is read before opening: `by_index` holds a mutable borrow of the archive for
        // the whole match, so the name must be cloned first. Both come from the same table, keyed by
        // the same index, so the recovered name can never disagree with the entry that failed.
        let name = zip.name_for_index(i).map(|n| n.trim_start_matches('/').to_string());
        let mut f = match zip.by_index(i) {
            Ok(f) => f,
            Err(_) => {
                let described = match &name {
                    Some(n) => format!("entry {i} ({n})"),
                    None => format!("entry {i}"),
                };
                acc.note(format!("{described} could not be read from the archive and was not checked"));
                acc.set_incomplete();
                match name {
                    // A directory entry: never register it as a part (the readable path skips
                    // directories too, and the unreadable path must not invent one).
                    Some(n) if n.ends_with('/') => entries.push(blank_entry(n, true)),
                    // Register the part as present-but-unchecked. Its content is marked unavailable,
                    // which is what makes every cross-part check that would conclude absence from it
                    // skip; the marker, not the mere registration, is the mechanism.
                    Some(n) => entries.push(blank_entry(n, false)),
                    // `name_for_index` and `by_index` index the same table and the loop is bounded
                    // by `zip.len()`, so this should be unreachable. If it happens, an entry of
                    // unknown identity exists: it could be any part, so no absence conclusion is
                    // established (see `Acc::set_unknown_unreadable` and `ABSENCE_RULES`).
                    None => unknown_unreadable = true,
                }
                continue;
            }
        };
        let name = f.name().trim_start_matches('/').to_string();
        if f.is_dir() {
            entries.push(blank_entry(name, true));
            continue;
        }
        let size = f.size();
        if size > limits.part_bytes {
            acc.note(format!("part {name} is larger than the {}-byte per-part limit and was not checked", limits.part_bytes));
            acc.set_incomplete();
            entries.push(blank_entry(name, false));
            continue;
        }
        if total.saturating_add(size) > limits.total_bytes {
            acc.note(format!("part {name} would take the package past the {}-byte total limit and was not checked", limits.total_bytes));
            acc.set_incomplete();
            entries.push(blank_entry(name, false));
            continue;
        }
        let mut buf = Vec::with_capacity(size.min(1 << 20) as usize);
        match (&mut f).take(limits.part_bytes + 1).read_to_end(&mut buf) {
            Ok(_) if buf.len() as u64 > limits.part_bytes => {
                acc.note(format!("part {name} decompresses past the {}-byte per-part limit and was not checked", limits.part_bytes));
                acc.set_incomplete();
                entries.push(blank_entry(name, false));
            }
            Ok(_) => {
                total = total.saturating_add(buf.len() as u64);
                entries.push(text_entry(name, buf));
            }
            Err(_) => {
                // Any part whose content could not be read leaves the run INCOMPLETE: a check that
                // depended on it could not run. (This subsumes the old main-part special case.)
                acc.note(format!("part {name} could not be decompressed and was not checked"));
                acc.set_incomplete();
                entries.push(blank_entry(name, false));
            }
        }
    }

    if unknown_unreadable {
        acc.set_unknown_unreadable();
    }
    let cd = central_directory(bytes, acc.limits.entries);
    check_duplicate_entries(cd.as_ref(), acc);
    check_case_collisions(cd.as_ref(), &entries, acc);

    let ct_at = entries.iter().position(|e| !e.is_dir && e.name.eq_ignore_ascii_case("[Content_Types].xml"));
    acc.ran("PKG-NO-CONTENT-TYPES");
    let content_types_present = ct_at.is_some();
    // The archive suffix may hold the manifest; a prefix cannot establish its absence.
    if !content_types_present && !entries_truncated {
        acc.add("PKG-NO-CONTENT-TYPES", None, "the package has no [Content_Types].xml part, so part content types cannot be resolved".to_string());
    }
    let mut content_types = ContentTypes { incomplete: !content_types_present && entries_truncated, ..ContentTypes::default() };
    let mut ct_guard = ParseGuard::new(limits.events, limits.depth);
    if let Some(e) = ct_at.and_then(|i| entries.get(i))
        && let Some(text) = &e.decoded
        && parse_content_types(text, &mut content_types, limits.entries, &mut ct_guard)
    {
        content_types.incomplete = true;
        acc.note(format!("[Content_Types].xml declares more than {} entries; later ones were not recorded", limits.entries));
        acc.set_incomplete();
    }
    if ct_guard.exhausted() {
        content_types.incomplete = true;
        acc.note(format!("[Content_Types].xml exceeded the XML {} budget; later declarations were not recorded", ct_guard.budget()));
        acc.set_incomplete();
    }

    content_types.incomplete |= ct_at.and_then(|i| entries.get(i)).is_some_and(|e| e.content_unavailable);
    if content_types.incomplete {
        // Parser errors suppress manifest-dependent checks just as budget stops do.
        acc.note("[Content_Types].xml declarations were not fully examined; dependent absence checks were skipped".to_string());
        acc.set_incomplete();
    }

    let rels = load_rels(&entries, acc);

    // Classify XML parts once (J4) and decode every classified part, whichever its file name, so a
    // supporting or story part with an unconventional name still has its checks run (H5). The
    // classification is content type (+xml / text/xml / the rels type) OR a recognised relationship
    // role.
    let xml_parts = classified_xml_parts(&entries, &content_types, &rels);
    for e in entries.iter_mut().filter(|e| !e.is_dir) {
        if e.decoded.is_some() || e.decode_error.is_some() || e.bytes.is_none() {
            continue;
        }
        if xml_parts.contains(&e.name.to_ascii_lowercase()) {
            decode_entry(e);
        }
    }

    acc.ran("PKG-NO-MAIN");
    let package_rels = rels.iter().find(|r| r.name.eq_ignore_ascii_case("_rels/.rels"));
    let main_ambiguous = competing_targets(package_rels, is_office_document_relationship);
    if main_ambiguous {
        acc.note(
            "ambiguous officeDocument selection for the package: distinct official targets compete; owner-dependent document checks were skipped"
                .to_string(),
        );
        acc.set_incomplete();
    }
    let main = package_rels
        .and_then(|rp| rp.rels.iter().find(|r| !r.external && is_office_document_relationship(&r.kind)))
        .and_then(|r| r.target_abs.as_deref())
        .and_then(|t| canonical(&entries, t));
    let package_rels_unavailable = entries.iter().any(|e| !e.is_dir && e.name.eq_ignore_ascii_case("_rels/.rels") && e.content_unavailable);
    let discovery_complete = !entries_truncated && !unknown_unreadable && !package_rels_unavailable && !package_rels.is_some_and(|rp| rp.incomplete);
    let main =
        if main_ambiguous { Resolution::Ambiguous("distinct official targets compete") } else { Resolution::discovered(main, discovery_complete) };
    if matches!(main, Resolution::Absent) {
        acc.add("PKG-NO-MAIN", None, no_main_message(package_rels));
    }
    let main_name = match &main {
        Resolution::One(name) => Some(name.as_str()),
        Resolution::Absent | Resolution::Ambiguous(_) | Resolution::Unknown(_) => None,
    };
    let glossary = if main_ambiguous {
        Resolution::Unknown("package main is ambiguous")
    } else {
        glossary_part(&entries, &content_types, &rels, main_name, !entries_truncated && !unknown_unreadable)
    };
    let glossary_ambiguous = matches!(glossary, Resolution::Ambiguous(_));
    if let Resolution::Ambiguous(reason) = &glossary {
        acc.note(format!("ambiguous glossaryDocument selection: {reason}; owner-dependent document checks were skipped"));
        acc.set_incomplete();
    }
    let roots_ambiguous = main_ambiguous || glossary_ambiguous;
    let reachable = reachability(&rels, main_name);
    Some(Package {
        entries,
        content_types,
        content_types_present,
        rels,
        main,
        glossary,
        roots_ambiguous,
        reachable,
        xml_parts,
        entries_truncated,
        identity_incomplete: unknown_unreadable,
    })
}

/// Whether official relationships for one singleton role name distinct internal target parts.
